P15-merge-two-sorted-lists#recursive:
def merge_two_lists(l1, l2):
    if not l1 or not l2:
        return l1 or l2
    if l1.val <= l2.val:
        l1.next = merge_two_lists(l1.next, l2)   # one stack frame per node
        return l1
    l2.next = merge_two_lists(l1, l2.next)
    return l2

