def merge_k_lists(lists):
    def merge_two(a, b):
        dummy = tail = ListNode()
        while a and b:
            if a.val <= b.val:
                tail.next, a = a, a.next
            else:
                tail.next, b = b, b.next
            tail = tail.next
        tail.next = a or b
        return dummy.next

    merged = None
    for head in lists:
        merged = merge_two(merged, head)   # merged keeps growing: O(k·N)
    return merged

P15-merge-k-sorted-lists:
def merge_k_lists(lists):
    def merge_two(a, b):
        dummy = tail = ListNode()
        while a and b:
            if a.val <= b.val:
                tail.next, a = a, a.next
            else:
                tail.next, b = b, b.next
            tail = tail.next
        tail.next = a or b
        return dummy.next

    if not lists:
        return None
    interval = 1
    while interval < len(lists):       # rounds: merge pairs at doubling gaps
        for i in range(0, len(lists) - interval, interval * 2):
            lists[i] = merge_two(lists[i], lists[i + interval])
        interval *= 2
    return lists[0]
